/**
 * Narrow check for a canonical v1–v5 UUID string. Used where a claim may carry either a UUID
 * (e.g. `students.id`) or an opaque code (e.g. a student login code) in the same field.
 */
export function isUuid(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)
  );
}

/**
 * Legacy `<epoch ms>-<9 base-36 chars>` id used for transcript ids, originally
 * generated by the blob-era data service. Kept in the same format so existing transcript ids stay valid.
 */
export function generateLegacyId(): string {
  return `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
}

/**
 * `@Transform` helper: trims and lowercases a UUID string so JS-side comparisons match what
 * Postgres returns (`uuid` columns come back lowercase; `@IsUUID` accepts either case).
 * Non-strings pass through for the validators to reject.
 */
export function toCanonicalUuid(value: unknown): unknown {
  return typeof value === 'string' ? value.trim().toLowerCase() : value;
}

/** `toCanonicalUuid` for each entry of an array; a non-array passes through. */
export function toCanonicalUuids(value: unknown): unknown {
  return Array.isArray(value) ? value.map((entry: unknown) => toCanonicalUuid(entry)) : value;
}
